import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>一个网站的速度取决于它的图片。文字几毫秒就能加载，一张没优化过的照片却能让页面卡住好几秒。</p>\n<p><a href=\"/zh/wangye-tupian-youhua/\">网页图片优化工具</a>就是为这个问题做的。它会针对网站上具体的图片位置压缩图片，然后把可以直接粘贴到页面的HTML代码交给你。</p>\n<p>这篇指南会讲清楚预设、设置，以及怎样用这个工具让整个网站变快。</p>\n<h2 id=\"what-is-web-optimisation\">什么是网页图片优化？</h2>\n<p>网页优化是为图片在页面上的具体工作做准备。首图、商品照和缩略图需要的尺寸和格式各不相同。</p>\n<p>它包括四个方面：文件大小、尺寸、格式和HTML。四个都做对了，图片加载又快、看起来又锐利。</p>\n<p>文件大小决定下载速度。尺寸决定图片怎么放进它的位置。格式决定兼容性和画质。</p>\n<p>HTML决定浏览器怎么对待图片。懒加载、宽度、高度和替代文字都写在标签里，它们都影响速度和无障碍。</p>\n<p>优化工具把这四件事一起处理。这就是它和普通压缩工具的区别，普通压缩工具只处理文件大小。</p>\n<h2 id=\"presets-explained\">五个网页性能预设</h2>\n<p>工具提供五个预设，每个都对应网站上一个真实的位置。它们一键设定尺寸、格式和画质。</p>\n<p>电商商品是默认预设。它把图片上限设为1200像素宽，WebP格式，82%的画质，非常适合商品照片。</p>\n<p>其他预设覆盖首图、卡片、缩略图和社交分享。每个预设都和它名字对应的位置相匹配。</p>\n<p>预设是起点，不是牢笼。选了预设之后，任何设置都可以自定义，混搭出适合你页面的组合。</p>\n<p>先选最接近你的位置的预设。只有结果不适合设计时，才从那里开始调整。</p>\n<h2 id=\"hero-images\">优化首图</h2>\n<p>首图铺满页面顶部，所以它对第一印象和最大内容绘制（LCP）最重要。</p>\n<p>首图要大到在宽屏幕上看起来锐利，但不能更大。过大的首图会把带宽浪费在没人看得到的像素上。</p>\n<p>现代网站的首图用WebP。同样画质下，它比JPG的体积更轻。</p>\n<p>首图千万不要懒加载。它在首屏上方，浏览器应该立刻下载它，而不是等着滚动。</p>\n<p>条件允许时，预加载首图。提前告诉浏览器最重要的那张图片，能实实在在地缩短首次绘制的时间。</p>\n<h2 id=\"product-images\">优化商品图片</h2>\n<p>商品图片是用来卖东西的，所以必须保持锐利。电商预设把它们上限设为1200像素，适合大多数店铺的版式。</p>\n<p>背景保持干净，商品放在正中间。整洁的商品照压起来更好，看起来也更专业。</p>\n<p>整个商品目录用一致的尺寸。尺寸混杂的网格看起来不整齐，不管压缩得多好都没用。</p>\n<p>现代网店的商品照片用WebP最理想。要求JPG的电商平台，换格式、保持同样的尺寸就行。</p>\n<p>上传后在手机上检查商品页面。大多数顾客用手机浏览，图片首先要在手机上好看。</p>\n<h2 id=\"cards-thumbnails\">卡片和缩略图</h2>\n<p>卡片和缩略图显示得很小，所以需要的数据最少。一张显示300像素宽的卡片，400像素的图片完全够用。</p>\n<p>小图片能容忍更重的压缩。显示尺寸会藏住柔和，低画质的缩略图看起来依然干净。</p>\n<p>首屏以下的卡片用懒加载。页面打开时它们还看不见，浏览器可以晚一点再下载。</p>\n<p>卡片之间的长宽比保持一致。长宽比混杂的网格看起来很乱，还会迫使浏览器重新排版。</p>\n<p>缩略图是优化回报最大的地方。一个有二十张卡片的页面，每张缩略图做好尺寸，能省下好几MB。</p>\n<h2 id=\"copy-img-button\">“复制图片标签”按钮</h2>\n<p>“复制图片标签”按钮会写出优化后图片的完整HTML。它包括图片来源、尺寸、替代文字和加载行为。</p>\n<p>替代文字是根据文件名或你的描述生成的。生成的文字描述得不好时，编辑一下。</p>\n<p>标签里包括宽度和高度属性。它们能防止布局偏移，这是影响排名的核心网页指标之一。</p>\n<p>首屏以下的图片会带上懒加载。它告诉浏览器，等到图片接近可视区域时再下载。</p>\n<p>标签可以直接粘贴到页面里。拿来就能用，不用手动编辑。</p>\n<h2 id=\"lazy-loading\">懒加载的正确做法</h2>\n<p>懒加载会推迟图片下载，直到需要它的时候。这是任何图片多的页面上最容易的速度提升。</p>\n<p>用在首屏以下的图片上。页面打开时它们还看不见，提前下载就是浪费带宽。</p>\n<p>首图和标志千万不要懒加载。它们立刻就能看到，推迟它们会伤害第一印象和LCP分数。</p>\n<p>优化工具会为合适的预设自动加上懒加载。首图预设不会加，这才是正确的行为。</p>\n<p>加上懒加载后测试页面。往下滚动，确认图片进入视野时平滑地出现。</p>\n<h2 id=\"formats-web\">网页用的格式</h2>\n<p>WebP是大多数网页图片最好的格式。同样画质下，它比JPG更小，还像PNG一样支持透明背景。</p>\n<p>JPG对兼容性来说依然不可或缺。邮件、社交分享和老系统还是更喜欢JPG，社交OG预设会自动切换到它。</p>\n<p>PNG适合界面图形，不适合照片。标志或图标用PNG能做到像素级完美，照片用PNG则会浪费带宽。</p>\n<p>SVG不在这个工具的处理范围内。它是矢量格式，优化工具处理的是JPG、PNG和WebP这样的位图。</p>\n<p>拿不准时，网站上用WebP，分享时用JPG。优化工具让两者之间的切换变成一键的事。</p>\n<h2 id=\"quality-slider\">画质滑块：20%到95%</h2>\n<p>画质滑块从20%到95%，而不是0到100%。这个范围是有意的，它能保护你不做出糟糕的选择。</p>\n<p>低于20%，图片会明显散架。没有网站位置能从这么低的画质里受益，所以工具不提供它。</p>\n<p>高于95%，文件会快速变大，肉眼却几乎看不出提升。多出来的数据保存的是眼睛看不见的细节。</p>\n<p>大多数预设在75%到85%之间。这个范围在很小的文件体积下，对几乎每张图片都能做出干净的结果。</p>\n<p>只有预设结果不适合图片时，才调整滑块。细节丰富的照片可能想要85%，简单的图形70%就够了。</p>\n<h2 id=\"exif-stripping\">去掉EXIF与页面重量</h2>\n<p>相机照片里藏着元数据：GPS位置、相机型号和拍摄设置。这些数据会增加体积，还会泄露隐私信息。</p>\n<p>优化工具会在压缩过程中去掉EXIF和GPS数据。下载下来的文件不记录照片在哪里、什么时候拍的。</p>\n<p>去掉元数据每张图片只能省几KB，但加起来很可观。二十张图片一起能省下有意义的体积。</p>\n<p>隐私是更大的好处。发布在公开网站上的照片，不应该包含拍摄地点。</p>\n<p>客户项目里，去掉元数据是必需的。未发布的商品和私人地点，绝不能通过图片元数据泄露出去。</p>\n<h2 id=\"batch-web\">整个网站的批量优化</h2>\n<p>你可以一次优化多张图片。把三十张博客图片拖进来，选一个预设，一起下载。</p>\n<p>批量模式最适合网站迁移。博客换新主题意味着每张图片都要重新优化，批量处理几分钟就搞定了。</p>\n<p>下载整批之前，先抽查几张结果。一张发虚的图片很容易藏在一堆好结果中间。</p>\n<p>整批保持预设一致。混杂的设置会做出混杂的结果，在线上看起来不整齐。</p>\n<p>要的是精确的文件大小目标而不是预设时，<a href=\"/zh/mubiao-wenjian-daxiao-yasuo/\">目标文件大小压缩工具</a>可以输入任意数字。</p>\n<h2 id=\"og-images\">社交分享与OG图片</h2>\n<p>别人分享你的页面时，平台会显示一张预览图。这张图片常常是新访客看到的第一个东西。</p>\n<p>OG图片需要特定的尺寸，通常是1200×630像素。社交OG预设能正确设定尺寸，并切换到JPG。</p>\n<p>文件保持在几百KB以下。预览图太重时，在分享卡片里加载很慢，有些平台干脆直接跳过它。</p>\n<p>发布之前测试分享卡片。每个主流平台都有调试工具，能精确显示预览的样子。</p>\n<p>好的分享图片简单又醒目。文字要大，主体要居中，背景不要杂乱。</p>\n<h2 id=\"retina-web\">视网膜屏和高DPI屏幕</h2>\n<p>视网膜屏在同样的物理尺寸里塞了更多像素。在普通屏幕上锐利的图片，在视网膜屏上可能显得发虚。</p>\n<p>解决方法是提供显示尺寸两倍宽的图片。显示400像素宽的缩略图，文件里就应该是800像素。</p>\n<p>优化工具的预设已经考虑到了这一点。卡片预设做出来的图片，在高DPI屏幕上保持锐利，又不浪费带宽。</p>\n<p>小缩略图上这点差别不大。大尺寸的头图上，标准版和视网膜版的差别看得见。</p>\n<p>条件允许时，在真实的高DPI屏幕上测试。看结果的截图会藏住你正想检查的那种发虚。</p>\n<h2 id=\"alt-text-web\">替代文字与无障碍</h2>\n<p>每张网页图片都需要替代文字。它为屏幕阅读器和搜索引擎描述图片，图片加载失败时也会显示出来。</p>\n<p>优化工具会根据文件名或你的描述生成替代文字。生成的文字描述得不好时，编辑一下。</p>\n<p>替代文字写成一句话。描述图片里有什么，而不是它是干什么用的，长度控制在125个字符左右。</p>\n<p>装饰性图片需要空的替代文字，而不是描述。空白的替代文字会告诉屏幕阅读器直接跳过这张图片。</p>\n<p>好的替代文字也有助于SEO。搜索引擎靠它理解图片，这能从图片搜索带来流量。</p>\n<h2 id=\"cdn-caching\">CDN与图片缓存</h2>\n<p>内容分发网络会从离访客最近的服务器提供图片。这能缩短下载时间，对全球观众尤其如此。</p>\n<p>优化过的图片从CDN里受益最大。附近提供的小文件几乎瞬间加载，远处提供的大文件却爬得很慢。</p>\n<p>缓存头会告诉浏览器把图片保存在本地。回头客再次加载页面时，就不用重新下载图片了。</p>\n<p>很少变化的图片，缓存时间设得长一点。标志或商品照片缓存几个月都没问题。</p>\n<p>优化和分发是配合工作的。快速CDN上的小图片，每次都胜过慢速服务器上的大图片。</p>\n<h2 id=\"webp-fallback\">WebP加JPG备用方案</h2>\n<p>有些老浏览器打不开WebP。只提供WebP，那些访客看到的会是损坏的图片。</p>\n<p>picture元素能解决这个问题。它先列WebP、再列JPG，浏览器会选它支持的第一个格式。</p>\n<p>每张图片生成两个版本。优化工具做WebP的副本，同一个预设做出来的JPG副本作为备用。</p>\n<p>在老浏览器或设备上测试备用方案。JPG版本应该无缝出现，看不出任何差别。</p>\n<p>WebP的支持越来越广，备用方案的重要性会越来越小。目前，它是防止图片损坏的廉价保险。</p>\n<h2 id=\"measuring-web\">衡量改善的效果</h2>\n<p>优化前后的数字能让好处变得具体。记下优化前的图片总重量和加载时间，再优化后测量一次。</p>\n<p>一个普通的页面能从几MB降到1MB以下。这个变化会立刻体现在速度分数和页面的感觉上。</p>\n<p>优化后检查核心网页指标。LCP的改善最大，因为首图通常是最大的绘制内容。</p>\n<p>请同事用手机加载页面。真实设备、真实网络下的测试，才是对你工作的诚实检验。</p>\n<p>简单记录一下省下来的数据。有人问为什么图片必须优化时，数字比任何争论都有说服力。</p>\n<p>想看动手操作的步骤，可以读<a href=\"/zh/blog/ru-he-you-hua-tu-pian-ti-sheng-wang-zhan-su-du/\">如何优化图片提升网站速度</a>。想深入了解核心网页指标，可以看<a href=\"/zh/blog/tu-pian-you-hua-he-xin-wang-ye-zhi-biao-lcp-yu-wen-jian-da-xiao/\">图片优化与核心网页指标：LCP与文件大小</a>。只需要简单的大小目标时，<a href=\"/zh/tupian-yasuo-dao-200kb/\">200KB压缩工具</a>能覆盖大多数网页图片。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"首图应该用哪个预设？","answer":"用首图预设，它会按全宽横幅的尺寸设定图片，并保持高画质。首图千万不要懒加载，因为它在首屏上方，会影响最大内容绘制（LCP）。网站支持时用WebP，同样画质下文件最小。"},{"question":"为什么工具给社交分享图片切换到JPG？","answer":"社交平台和邮件客户端处理JPG比WebP更可靠。社交OG和邮件预设会自动切换格式，让你的分享图片在任何地方都能正确显示，即使是打不开WebP的老系统也不例外。"},{"question":"首图应该保留懒加载吗？","answer":"不应该。懒加载会等到图片接近可视区域时才下载，首图立刻就能看到，这样做是错的。它会伤害你的最大内容绘制分数。懒加载只用在首屏以下的图片上。"},{"question":"“仅缩小”选项是干什么的？","answer":"它能保护小图片不被放大。打开后，工具只缩小比预设尺寸大的图片，比预设小的图片保持原样。这样图标和缩略图能保持清晰，而不是被拉伸。"},{"question":"为什么下载的文件名最后带-web？","answer":"-web后缀标明这个文件是网页优化过的版本，不会和原图弄混。hero-1200-web.webp这样的名字，一眼就能看出文件已经为网站准备好了。"},{"question":"能用网页图片优化工具代替批量图片压缩工具吗？","answer":"网站需要预设、HTML标签和按位置设定的尺寸时，用网页优化工具。只需要把文件变小、不需要网页专用设置时，用批量压缩工具。需要精确的文件大小上限时，用目标文件大小压缩工具。"}];
